func commentifyString(in string) string {
	var newlines []string
	lines := strings.Split(in, "\n")
	for _, x := range lines {
		if !strings.HasPrefix(x, "//") {
			newlines = append(newlines, "// "+x)
		} else {
			newlines = append(newlines, x)
		}
	}
	return strings.Join(newlines, "\n")
}

